inputs = ['yfzwk', 'ijfagw', 'uhjw', 'uj', 'eb']
outputs = ['yfzwk', 'ijfagw', 'jihjw', 'cjv', 'eb']

print("Let me examine all the strings more systematically:")

print("\nAll inputs:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}' (len={len(inp)})")

print("\nAll outputs:")  
for i, outp in enumerate(outputs):
    print(f"  {i}: '{outp}' (len={len(outp)})")

print("\nDifferences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"  {i}: '{inp}' -> '{outp}'")
        # Show character by character differences
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"    pos {j}: '{inp[j]}' -> '{outp[j]}'")
        if len(inp) != len(outp):
            print(f"    length change: {len(inp)} -> {len(outp)}")
    else:
        print(f"  {i}: '{inp}' unchanged")

print("\nLooking for common patterns:")
# Look for repeated substrings or common elements
all_chars = set()
for s in inputs + outputs:
    all_chars.update(s)
print("All unique characters:", sorted(all_chars))

# Check if any strings are substrings of others
print("\nChecking substring relationships:")
for i, inp in enumerate(inputs):
    for j, outp in enumerate(outputs):
        if i != j:
            if inp in outp:
                print(f"'{inp}' is substring of '{outp}'")
            if outp in inp:
                print(f"'{outp}' is substring of '{inp}'")

